<template>
    <div class="container">
        <h1>Tabla Clientes</h1>
        <table>
            <thead>
                <tr>
                    <th>codigo</th>
                    <th>idcliente</th>
                    <th>nombre</th>
                    <th>apellido</th>
                    <th>telefono</th>
                </tr>
            </thead>
            <tbody>
                <tr v-for="cliente in clientes" :key="cliente.codigo">
                    <td>{{ cliente.codigo }}</td>
                    <td>{{ cliente.idcliente }}</td>
                    <td>{{ cliente.nombre }}</td>
                    <td>{{ cliente.apellido }}</td>
                    <td>{{ cliente.telefono }}</td>
                </tr>
            </tbody>
        </table>
    </div>


</template>
<script>
import axios from 'axios';

export default{

    data(){

        return{
        clientes:[],
        };
    },
    methods:{

        obtenerClientes(){
            console.log("obtener clientes");

            axios.get("https://proyecto-production-b957.up.railway.app/api/clientes/Listar")
            .then((response)=>{

                this.clientes=response.data;
            })
            .catch((error)=>{
                alert("lista fallo",error);
            });
        },
    },

    mounted(){

        this.obtenerClientes();
    },
}

</script>