<template>

    <div class="container">
        <h1>Formulario Clientes</h1>
        <form action="" id="client-form" @submit.prevent="guardar">

            <div class="form-group">
                <label for="codigo">Codigo: </label>
                <input type="text" id="codigo" name="codigo" required v-model="codigo">
            </div>

            <div class="form-group">
                <label for="idcliente">idcliente: </label>
                <input type="text" id="idcliente" name="idcliente" required v-model="idcliente">
            </div>

            <div class="form-group">
                <label for="nombre">Nombre: </label>
                <input type="text" id="nombre" name="nombre" required v-model="nombre">
            </div>

            <div class="form-group">
                <label for="apellido">Apellido</label>
                <input type="text" id="apellido" name="apellido" required v-model="apellido">
            </div>

            <div class="form-group">
                <label for="telefono">Telefono</label>
                <input type="text" id="telefono" name="telefono" required v-model="telefono">
            </div>

            <button type="submit">Guardar</button><br>
            <button type="button" @click="eliminar">Eliminar</button><br>
            <button type="button" @click="actualizar">Actualizar</button><br>
            <button type="button" @click="consultar">Consultar</button><br>

        </form>

    </div>

</template>
<script>

import axios from 'axios'; 

export default {

    data(){

        return{

            codigo:"",
            idcliente:"",
            nombre:"",
            apellido:"",
            telefono:""

        };
    },

    methods:{

        guardar(){

            axios.post("hhttps://proyecto-production-b957.up.railway.app/api/clientes",{

                codigo: this.codigo,
                idcliente: this.idcliente,
                nombre: this.nombre,
                apellido: this.apellido,
                telefono: this.telefono,
            })
            .then((response)=>{
                console.log("Cliente registrado con exito", response.data);
                alert("Usuario registrado");
                this.codigo="";
                this.idcliente="";
                this.nombre="";
                this.apellido="";
                this.telefono="";

                this.$emit("actualizar-tabla");
            })
            .catch((error)=>{
                console.error("Error al registrarel el usuario", error);
            });

        },
        consultar(){
            axios.get("https://proyecto-production-b957.up.railway.app/api/clientes/"+this.codigo)
            .then((response)=>{

                this.idcliente=response.data.idcliente;
                this.nombre=response.data.nombre;
                this.apellido=response.data.apellido;
                this.telefono=response.data.telefono

            })
            .catch((error)=>{
                alert("Consulta fallo",error);
            });
        },
        actualizar(){

            axios.put("https://proyecto-production-b957.up.railway.app/api/clientes/actualizar/"+ this.codigo,{

                codigo:this.codigo,
                idcliente:this.idcliente,
                nombre:this.nombre,
                apellido:this.apellido,
                telefono:this.telefono,
        
            } )
            .then((response)=>{

                alert("Cliente actualizado con exito", response.data);
            })
            .catch((error)=>{
                alert("Actualizacion fallo", error);
            });
        },
        eliminar(){

            axios.delete("https://proyecto-production-b957.up.railway.app/api/clientes/"+this.codigo)
            
            .then(()=>{

                alert("Usuario eliminado");
                this.$emit("actualizar-tabla");
            })
            .catch((error)=>{
                alert("eliminacion fallo",error);
            });
        },

    },
};


</script>